import React, { useState } from "react";
import { submitContactForm } from "../api";

const initialForm = {
  name: "",
  email: "",
  phone: "",
  subject: "",
  message: "",
};

const Contact = () => {
  const [form, setForm] = useState(initialForm);
  const [loading, setLoading] = useState(false);
  // status: { type: 'success' | 'info' | 'error', text: string }
  const [status, setStatus] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus(null);

    if (!form.name.trim() || !form.email.trim() || !form.message.trim()) {
      setStatus({ type: "error", text: "Please fill in your name, email, and message." });
      return;
    }

    setLoading(true);
    try {
      const res = await submitContactForm(form);
      const { success, duplicate, message } = res.data;

      if (success && duplicate) {
        // They already submitted recently and it hasn't been reviewed yet.
        setStatus({ type: "info", text: message });
      } else if (success) {
        setStatus({ type: "success", text: message });
        setForm(initialForm);
      } else {
        setStatus({ type: "error", text: message || "Something went wrong. Please try again." });
      }
    } catch (err) {
      const serverMessage = err?.response?.data?.message;
      setStatus({
        type: "error",
        text: serverMessage || "We couldn't send your message. Please check your connection and try again.",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <section className="page-hero">
        <div className="page-hero-inner">
          <p className="eyebrow-plain">Contact</p>
          <h1>Let's talk about your website.</h1>
          <p className="hero-sub">
            Fill in the form and our team will get back to you shortly. For urgent
            enquiries, email us directly at{" "}
            <a href="mailto:rohanjantre123@gmail.com">rohanjantre123@gmail.com</a>.
          </p>
        </div>
      </section>

      <section className="section contact-section">
        <div className="contact-grid">
          <div className="contact-info">
            <h2>Get in touch</h2>
            <p>
              Tell us a little about your business and what you're looking to build.
              We typically reply within one business day.
            </p>
            <div className="contact-info-item">
              <span className="contact-info-label">Email</span>
              <a href="mailto:rohanjantre123@gmail.com">rohanjantre123@gmail.com</a>
            </div>
            <div className="contact-info-item">
              <span className="contact-info-label">Hours</span>
              <span>Mon &ndash; Sat, 10am &ndash; 7pm IST</span>
            </div>
          </div>

          <form className="contact-form" onSubmit={handleSubmit} noValidate>
            <div className="form-row">
              <label htmlFor="name">Full name</label>
              <input
                id="name"
                name="name"
                type="text"
                placeholder="Your name"
                value={form.name}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-row">
              <label htmlFor="email">Email address</label>
              <input
                id="email"
                name="email"
                type="email"
                placeholder="you@example.com"
                value={form.email}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-row">
              <label htmlFor="phone">Phone number (optional)</label>
              <input
                id="phone"
                name="phone"
                type="tel"
                placeholder="+91 90000 00000"
                value={form.phone}
                onChange={handleChange}
              />
            </div>

            <div className="form-row">
              <label htmlFor="subject">Subject</label>
              <input
                id="subject"
                name="subject"
                type="text"
                placeholder="e.g. New website for my business"
                value={form.subject}
                onChange={handleChange}
              />
            </div>

            <div className="form-row">
              <label htmlFor="message">Message</label>
              <textarea
                id="message"
                name="message"
                rows="5"
                placeholder="Tell us about your project..."
                value={form.message}
                onChange={handleChange}
                required
              ></textarea>
            </div>

            {status && (
              <div className={`form-status form-status-${status.type}`} role="alert">
                {status.text}
              </div>
            )}

            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? "Sending..." : "Send message"}
            </button>
          </form>
        </div>
      </section>
    </>
  );
};

export default Contact;
